// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // 1. bound to admissible domain: fee rate must be <= 5000 for successful initialization
        //    but we also allow >5000 to observe the revert case
        // 2. try to initialize with the given fee rate, ignoring whether it reverts
        try c.initialize(
            address(0x1),
            address(0x2),
            100,
            100,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            // success - feeRate must be <= 5000
            assertTrue(c.feeRate() <= 5000);
        } catch {
            // revert - feeRate may be anything, but the invariant only applies on success
            // we skip assertion on revert
        }
    }
}

